<template>
  <AppShell><header class="page-head"><span class="eyebrow"><MessagesSquare :size="15" />DIALOGUE PROFILE</span><h1>对话式画像采集</h1><p>围绕十个维度逐步完善，已有画像时将生成新版本。</p></header>
    <div class="dimension-progress"><div><span>采集进度</span><b>{{ progress }} / 10</b></div><div class="progress-track"><i :style="{width:`${progress*10}%`}"></i></div><div class="dimension-dots"><i v-for="n in 10" :key="n" :class="{done:n<=progress}"></i></div></div>
    <section ref="messagePane" class="chat-pane" aria-live="polite"><article v-for="message in messages" :key="message.id" class="chat-message" :class="message.role"><span>{{ message.role==='user'?'我':'AI' }}</span><div><p>{{ message.text }}</p><small v-if="message.dimension">{{ message.dimension }}</small></div></article><div v-if="sending" class="typing"><span></span><span></span><span></span></div></section>
    <p v-if="error" class="form-error">{{ error }}</p>
    <form class="chat-composer" @submit.prevent="send"><label class="attach-btn" aria-label="上传学习材料"><Paperclip :size="19" /><input ref="fileInput" type="file" multiple accept="image/*,.pdf,.doc,.docx,.txt" @change="selectFiles" /></label><textarea v-model.trim="draft" rows="1" placeholder="输入你的回答…" :disabled="sending"></textarea><button type="submit" :disabled="sending||(!draft&& !attachments.length)" aria-label="发送"><Send :size="19" /></button></form><div v-if="attachments.length" class="attachment-row"><span v-for="file in attachments" :key="file.name"><FileText :size="13" />{{ file.name }}</span></div>
  </AppShell>
</template>
<script setup>
import { nextTick,onMounted,ref } from 'vue';import { FileText,MessagesSquare,Paperclip,Send } from 'lucide-vue-next';import AppShell from '../components/AppShell.vue';import { streamProfileChat,uploadInputs } from '../services/api.js'
const messages=ref([]),draft=ref(''),attachments=ref([]),sending=ref(false),error=ref(''),progress=ref(0),messagePane=ref(null)
function add(role,text,dimension=''){if(!text)return;messages.value.push({id:`${Date.now()}-${messages.value.length}`,role,text:String(text),dimension});nextTick(()=>messagePane.value?.scrollTo({top:messagePane.value.scrollHeight,behavior:'smooth'}))}
function consume(event){const d=event.data||{};const type=event.event||d.event;if(d.progress!=null)progress.value=Math.min(10,Math.max(progress.value,Math.round(Number(d.progress)/10)));if(d.completedDimensions)progress.value=Math.max(progress.value,Number(d.completedDimensions));const text=d.reply||d.message||d.content||d.question;if(text&&['message','assistant','complete','result'].includes(type))add('assistant',text,d.dimension||'')}
async function send(){const text=draft.value;const files=[...attachments.value];draft.value='';attachments.value=[];add('user',text||'请分析我上传的材料');sending.value=true;error.value='';try{const uploaded=files.length?await uploadInputs(files,'profile'):[];await streamProfileChat({message:text,content:text,attachments:uploaded,route:'/m/profile/collect'},consume);if(!messages.value.some((m,i)=>i===messages.value.length-1&&m.role==='assistant'))add('assistant','已记录，请继续补充你的学习情况。')}catch(e){error.value=e.message}finally{sending.value=false}}
function selectFiles(e){attachments.value=[...e.target.files].slice(0,5);e.target.value=''}
onMounted(()=>add('assistant','我会通过目标、基础、薄弱点、偏好和时间投入等维度了解你。先说说你当前的学习目标吧。','学习目标'))
</script>
<style scoped>.dimension-progress{padding:13px;border:1px solid #cfe0d7;border-radius:7px;background:#eef6f2}.dimension-progress>div:first-child{display:flex;justify-content:space-between;color:#52655b;font-size:11px}.dimension-progress b{color:#176f4b}.dimension-progress .progress-track{margin-top:8px}.dimension-dots{display:grid;grid-template-columns:repeat(10,1fr);gap:4px;margin-top:8px}.dimension-dots i{height:4px;background:#d5dfda}.dimension-dots i.done{background:#176f4b}.chat-pane{height:calc(100dvh - 395px);min-height:260px;display:flex;flex-direction:column;gap:12px;margin:12px -4px 0;padding:4px 4px 14px;overflow-y:auto}.chat-message{display:flex;align-items:flex-start;gap:9px;max-width:92%}.chat-message>span{flex:0 0 30px;width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:#176f4b;color:white;font-size:10px;font-weight:800}.chat-message>div{padding:11px 13px;border:1px solid #dce5e0;border-radius:4px 8px 8px;background:white}.chat-message.user{align-self:flex-end;flex-direction:row-reverse}.chat-message.user>span{background:#2f68b2}.chat-message.user>div{background:#edf4fb}.chat-message p{margin:0;font-size:13px;line-height:1.65;white-space:pre-wrap}.chat-message small{display:block;margin-top:7px;color:#176f4b;font-size:9px}.typing{display:flex;gap:6px;padding:15px}.typing span{width:7px;height:7px;border-radius:50%;background:#176f4b;animation:bounce 1s infinite}.typing span:nth-child(2){animation-delay:.15s}.typing span:nth-child(3){animation-delay:.3s}@keyframes bounce{50%{transform:translateY(-5px)}}.chat-composer{position:sticky;bottom:calc(62px + env(safe-area-inset-bottom));z-index:5;display:grid;grid-template-columns:44px minmax(0,1fr) 44px;align-items:end;gap:6px;padding:8px;border:1px solid #d3dfd8;border-radius:7px;background:white;box-shadow:0 8px 24px rgba(26,48,37,.12)}.chat-composer textarea{min-height:44px;max-height:112px;padding:11px 4px;border:0;outline:0;resize:none}.attach-btn,.chat-composer button{width:44px;height:44px;display:grid;place-items:center;border:0;border-radius:6px;background:#edf4f0;color:#176f4b}.chat-composer button{background:#176f4b;color:white}.attach-btn input{display:none}.attachment-row{position:sticky;bottom:calc(118px + env(safe-area-inset-bottom));z-index:4;display:flex;gap:6px;overflow-x:auto;padding:8px 0;background:#f6f8f7}.attachment-row span{flex:0 0 auto;display:flex;align-items:center;gap:5px;padding:5px 7px;background:#edf4f0;color:#52665c;font-size:9px}.form-error{padding:9px;background:#fff0ec;color:#a04435;font-size:11px}@media (orientation:landscape) and (max-height:500px){.chat-pane{height:230px}.chat-composer{bottom:0}.attachment-row{bottom:58px}}</style>
